(function(){'use strict';function init(){addMobileMenuButton();setupMobileMenu();}function addMobileMenuButton(){const headerContent=document.querySelector('.header-content');if(!headerContent)return;const toggleBtn=document.createElement('button');toggleBtn.className='mobile-menu-toggle';toggleBtn.innerHTML='☰';toggleBtn.setAttribute('aria-label','Toggle menu');headerContent.appendChild(toggleBtn);const overlay=document.createElement('div');overlay.className='mobile-menu-overlay';document.body.appendChild(overlay);const nav=document.querySelector('.main-nav');if(nav){const closeBtn=document.createElement('button');closeBtn.className='mobile-menu-close';closeBtn.innerHTML='&times;';closeBtn.setAttribute('aria-label','Close menu');nav.insertBefore(closeBtn,nav.firstChild);}}function setupMobileMenu(){const toggleBtn=document.querySelector('.mobile-menu-toggle');const closeBtn=document.querySelector('.mobile-menu-close');const overlay=document.querySelector('.mobile-menu-overlay');const nav=document.querySelector('.main-nav');const dropdowns=document.querySelectorAll('.dropdown');if(!toggleBtn||!nav)return;toggleBtn.addEventListener('click',function(){nav.classList.add('active');overlay.classList.add('active');document.body.style.overflow='hidden';});function closeMenu(){nav.classList.remove('active');overlay.classList.remove('active');document.body.style.overflow='';}if(closeBtn){closeBtn.addEventListener('click',closeMenu);}if(overlay){overlay.addEventListener('click',closeMenu);}dropdowns.forEach(function(dropdown){const toggle=dropdown.querySelector('.dropdown-toggle');if(toggle){toggle.addEventListener('click',function(e){if(window.innerWidth<=768){e.preventDefault();dropdown.classList.toggle('active');}});}});window.addEventListener('resize',function(){if(window.innerWidth>768){closeMenu();}});}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();